Translate("deDE", "tirisfal-glades", {
	title = "Tirisfal",
	aliases = { "Tirisfal" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Tirisfal war einst das Herz von {link:lordaeron}Lordaeron{/link}. Seine langen grünen Täler ernährten das größte der Menschenreiche, und an seinem Ostrand stand die {link:capital-city}Hauptstadt{/link} des Königreichs. Nun sind die Lichtungen grau. Nebel hängt über verlassenen Höfen, die Mühlen drehen sich für niemanden, und die Krähen sind fett. Das Land gehört den {link:forsaken}Verlassenen{/link}, den Toten, die wieder zu eigenem Verstand erwachten. Von {link:brill}Brill{/link} und {link:undercity}Undercity{/link} aus verteidigen sie es gegen die Lebenden und die Toten gleichermaßen.]=],
		},
		{
			title = "Ursprünge",
			text = [=[Keine Chronik verzeichnet das Jahr, in dem die ersten Siedler nach Tirisfal kamen. Sie kamen aus {link:arathor}Arathor{/link}, in den langen Jahrhunderten nach den {link:troll-wars}Trollkriegen{/link}, und sie fanden fruchtbaren Boden und stille Wälder. Aus ihren Gehöften wuchs ein Königreich, und dieses Königreich nahm den Namen {link:lordaeron}Lordaeron{/link} an. In späteren Zeitaltern kauften Adelsfamilien aus dem alten Kernland der {link:arathi-highlands}Arathi{/link} große Güter in den Lichtungen. Die Agamands, denen die Mühlen im nördlichen Hochland gehörten, galten als die wohlhabendsten von allen.]=],
		},
		{
			title = "Die Gegenwart",
			text = [=[Die {link:forsaken}Verlassenen{/link} von {link:sylvanas-windrunner}Sylvanas Windrunner{/link} herrschen über Tirisfal, doch sie herrschen über ein Land im Krieg. Die {link:scourge}Geißel{/link} hält noch immer {link:agamand-mills}Agamands Mühlen{/link} und schlüpft am {link:the-bulwark}Bollwerk{/link} vorbei, der Mauer, die die Lichtungen gegen die Pestländer im Osten schützt. Der {link:scarlet-crusade}Scharlachrote Kreuzzug{/link} marschiert aus seinem Kloster im Nordosten aus und unterhält Wachtürme im ganzen Land. {link:gnolls}Gnolle{/link} plündern die Massengräber nach Leichen, um die Heere des Lichkönigs zu nähren. In der {link:capital-city}Hauptstadt{/link} arbeitet die {link:royal-apothecary-society}Königliche Apothekervereinigung{/link} an einer neuen Seuche, und die Todeswache hält lebende Gefangene im Keller einer Taverne, bis die Apotheker sie brauchen.

Auch neue Sorgen sind gekommen. Vor Kurzem schlug die Nekropole {red:naxxramas}Naxxramas{/red} gegen {link:undercity}Undercity{/link} zu, und die Splitter ihres großen Kristalls liegen noch verstreut auf den Feldern nahe der zerstörten Hauptstadt, wo der {link:cult-of-the-damned}Kult der Verdammten{/link} nach ihnen sucht. In den westlichen Bergen unterhält ein neuer Orden verlassener Paladine eine eigene Festung. Nur wenige ihres Volkes trauen ihnen.]=],
		},
		{
			title = "Bewohner",
			text = [=[• {b}Die Verlassenen.{/b} Die Todeswache patrouilliert auf den Straßen, die Exekutoren geben die Befehle, und jeden Tag erwachen Neuerstandene in der Gruft von {link:deathknell}Deathknell{/link}.
• {b}Die {link:scourge}Geißel{/link}.{/b} Hirnlose Tote, Skelette und Nekromanten verseuchen noch immer die Mühlen, die Höfe und die alten Grüfte.
• {b}Der Scharlachrote Kreuzzug.{/b} Eiferer in Rot, die jeden Untoten verbrennen, den sie finden, ob er dem Lichkönig dient oder nicht.
• {b}Die Rot-Hide-{link:gnolls}Gnolle{/link}.{/b} Sklaven der Geißel, die die Toten ausgraben.
• {b}{link:murlocs}Murlocs{/link} und Bestien.{/b} Die Stämme der Vile Fin an Küste und Seen, Dunkelhunde, Dämmerfledermäuse und die großen Spinnen der östlichen Täler.]=],
		},
		{
			title = "Geschichte",
			text = [=[• {b}Die Seuche.{/b} Im {link:third-war}Dritten Krieg{/link} fegte die Seuche des {link:cult-of-the-damned}Kults der Verdammten{/link} über die Lichtungen. Ganze Familien starben und erhoben sich wieder als {link:scourge}Geißel{/link}.
• {b}Der Fall.{/b} Prinz {link:arthas-menethil}Arthas Menethil{/link} ermordete seinen Vater {link:terenas-menethil}Terenas Menethil{/link} in dessen eigenem Thronsaal. Die {link:capital-city}Hauptstadt{/link} fiel, und Tirisfal fiel mit ihr. Das war der {link:fall-of-lordaeron}Fall Lordaerons{/link}.
• {b}Die Verlassenen.{/b} Als der Griff des Lichkönigs schwächer wurde, rissen sich {link:sylvanas-windrunner}Sylvanas{/link} und ihre Anhänger los und nahmen die Ruinen der Hauptstadt in Besitz. Darunter erbauten sie {link:undercity}Undercity{/link}.
• {b}Die Nekropole.{/b} Als Naxxramas gegen Undercity zog, bekämpften die Verlassenen sie an der Oberfläche. Die {link:argent-dawn}Argentumdämmerung{/link} kämpfte an ihrer Seite, und viele fielen.]=],
		},
		{
			title = "Überlieferungen der Lichtungen",
			text = [=[• Die Verlassenen sagen, die Gruftwächter von {link:deathknell}Deathknell{/link} seien bereit gewesen, viele der Neuerstandenen zu verbrennen, bevor sie erwachten.
• Vor der Seuche brauten die zurückgezogen lebenden Leute von {link:shadowvale}Shadowvale{/link} ein grünes Elixier aus Kräutern der westlichen Hügel. Apotheker, Mystiker und Giftmischer suchten es gleichermaßen, selbst nachdem es in der {link:capital-city}Hauptstadt{/link} verboten worden war.]=],
		},
	},
})

Translate("deDE", "deathknell", {
	title = "Deathknell",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Deathknell ist ein kleines Dorf der Toten im Westen von {link:tirisfal-glades}Tirisfal{/link}. Seine Gruft steht auf einem Hügel über einer Kapelle und einem Friedhof. Hierher bringen die Verlassenen die Leichen, die sie finden, und hier erwachen viele aus dem Bann des Lichkönigs wieder zu eigenem Verstand. Der {link:undertaker-mordo}Totengräber Mordo{/link} empfängt sie. {link:shadow-priest-sarvis}Schattenpriester Sarvis{/link} erklärt ihnen, was aus ihnen geworden ist, und {link:executor-arren}Exekutor Arren{/link} teilt sie zur Arbeit ein. Das Dorf ist nicht sicher. Hirnlose Tote irren durch seine nördlichen Häuser, Spinnen füllen die Goldmine im Nachtwebergrund, und der Scharlachrote Kreuzzug unterhält ein Lager im Südosten.]=],
		},
	},
})

Translate("deDE", "brill", {
	title = "Brill",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Brill ist die wichtigste Stadt der Verlassenen in {link:tirisfal-glades}Tirisfal{/link}, an der Straße zwischen {link:deathknell}Deathknell{/link} und {link:undercity}Undercity{/link}. Sein Rathaus ist der Sitz von {link:magistrate-sevren}Magistrat Sevren{/link} und {link:executor-zygand}Exekutor Zygand{/link}, die die Todeswache der Lichtungen befehligen. Sein Friedhof wird von Apothekerlehrlingen gepflegt, und sein Gasthaus, die Taverne Zur Galgenschlinge, hat einen Keller, in dem gefangene {link:humans}Menschen{/link} und {link:dwarves}Zwerge{/link} auf die Experimente der Apotheker warten. Nicht weit von der Stadt steigen die Zeppeline der {link:horde}Horde{/link} von ihren Türmen auf, und in diesen Tagen hat sogar ein Lehrer verlassener Paladine einen Platz in Brill.]=],
		},
	},
})

Translate("deDE", "agamand-mills", {
	title = "Agamands Mühlen",
	aliases = { "Gruft der Familie Agamand" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Agamands Mühlen stehen im Hochland des nördlichen {link:tirisfal-glades}Tirisfal{/link}. Sie waren der Reichtum der Familie Agamand, des reichsten Hauses der Lichtungen. Als die Seuche kam, befestigten die Agamands ihr Heim und hießen ihre Arbeiter bleiben und kämpfen. Alle starben, und alle erhoben sich wieder. Nun sind die Mühlen der stärkste Außenposten der {link:scourge}Geißel{/link} in Tirisfal. An ihrem Nordende liegt die Gruft der Familie Agamand, wo ein skelettartiger Hauptmann namens Dargol die Ahnen der Familie erweckt hat, damit sie für den Lichkönig kämpfen.]=],
		},
	},
})

Translate("deDE", "solliden-farmstead", {
	title = "Sollidens Bauernhof",
	aliases = { "Solliden" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Sollidens Bauernhof liegt im westlichen {link:tirisfal-glades}Tirisfal{/link}, nördlich von {link:deathknell}Deathknell{/link}. Er ist einer der letzten Orte in den Lichtungen, an denen lebende {link:humans}Menschen{/link} noch die Felder bestellen. Die Kürbisse wachsen noch, und die Bauern bringen noch ihre Ernte ein, denn der Scharlachrote Kreuzzug beschützt sie von einem Turm im Westen aus. Die Verlassenen hassen den Hof für sein Leben. Die Apotheker von {link:brill}Brill{/link} finden dennoch eine Verwendung für seine Kürbisse. Auf den Klippen im Nordwesten erhebt sich {link:bandarion-keep}Bandarion Keep{/link}.]=],
		},
	},
})

Translate("deDE", "garren-s-haunt", {
	title = "Garrens Schlupfwinkel",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Garrens Schlupfwinkel ist ein Gehöft im Norden von {link:tirisfal-glades}Tirisfal{/link}, mit einem Bauernhaus, einer Scheune und weiten grauen Feldern. Keine Chronik verzeichnet, wer Garren war. Die Rot-Hide-{link:gnolls}Gnolle{/link} halten den Hof nun. Sie dienen der {link:scourge}Geißel{/link} und plündern die Massengräber im Südwesten, wo die Toten der ersten Seuche begraben wurden. Ihr Anführer ist ein Gnoll namens Maggot Eye, und die Stadt {link:brill}Brill{/link} hat ihn für seine Verbrechen an den Verlassenen zum Tode verurteilt. {link:executor-zygand}Exekutor Zygand{/link} hat demjenigen eine Belohnung versprochen, der das Urteil vollstreckt und seine Pfote zurückbringt.]=],
		},
	},
})

Translate("deDE", "venomweb-vale", {
	title = "Giftwebertal",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Das Giftwebertal ist ein weites Tal im äußersten Osten von {link:tirisfal-glades}Tirisfal{/link}, unterhalb der Höhen des {link:scarlet-monastery}Scharlachroten Klosters{/link}. Seine Wälder sind dicht mit Netzen verhangen. Die großen Spinnen, die dort nisten, tragen ein Gift, von dem die Apotheker von {link:brill}Brill{/link} glauben, dass es einst eine uralte Seuche bewahrte. In letzter Zeit hat die Todeswache auch eine abtrünnige Monstrosität in der Nähe des Tals umherstreifen sehen. Ein solches Geschöpf hätte das {link:the-bulwark}Bollwerk{/link} nicht unbemerkt passieren dürfen, und die Todeswache hält die Sache still. Am Nordrand des Tals unterhält der Scharlachrote Kreuzzug ein eigenes Lager.]=],
		},
	},
})

Translate("deDE", "scarlet-watch-post", {
	title = "Scharlachroter Wachposten",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Scharlachrote Wachposten ist ein Turm des {link:scarlet-crusade}Scharlachroten Kreuzzugs{/link} im Nordosten von {link:tirisfal-glades}Tirisfal{/link}, jenseits von Faols Ruheplatz. Er bewacht die nördlichen Zugänge zum Scharlachroten Kloster. Sein Befehlshaber, Hauptmann Melrache, ist den Verlassenen als rücksichtsloser Mann bekannt, und er geht nie ohne seine beiden Leibwächter. Der Turm ist einer von mehreren, die der Kreuzzug in den Lichtungen unterhält. Von jedem von ihnen reiten seine Patrouillen aus, um die Toten zu verbrennen. Hauptmann Perrine hält einen verfallenen Turm südwestlich von {link:brill}Brill{/link}, und Hauptmann Vachon einen weiteren im Südosten, nahe Balnirs Bauernhof.]=],
		},
	},
})

Translate("deDE", "brightwater-lake", {
	title = "Blendwassersee",
	aliases = { "Gunthers Zufluchtsort" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Blendwassersee ist der größte See von {link:tirisfal-glades}Tirisfal{/link}, nordöstlich von {link:brill}Brill{/link}. Auf einer Insel in seiner Mitte liegt Gunthers Zufluchtsort, das Lager eines Lichs namens {link:gunther-arcanus}Gunther Arcanus{/link}. Er ist frei vom Lichkönig, doch lange glaubte er, der Einzige zu sein, und seine Diener griffen jeden an, der sich näherte. Vor dem Südufer der Insel steht ein alter, blutiger Altar. Die Agentin der {link:scourge}Geißel{/link} {link:lillith-nefara}Lillith Nefara{/link} schläft dort, bis eine Kerze der Lockung sie weckt.]=],
		},
	},
})

Translate("deDE", "capital-city", {
	title = "Hauptstadt",
	aliases = { "Stadt Lordaeron" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Die Ruinen der Hauptstadt stehen am Ostrand von {link:tirisfal-glades}Tirisfal{/link}. Jahrhundertelang war sie der Sitz der Könige von {link:lordaeron}Lordaeron{/link}. Hier kehrte Prinz {link:arthas-menethil}Arthas Menethil{/link} aus Nordend heim und erschlug seinen Vater auf dessen Thron. Die Stadt wurde geplündert und in Trümmern zurückgelassen. Ihre zerbrochenen Mauern und ihr leerer Thronsaal bewachen nun den Weg hinab nach {link:undercity}Undercity{/link}, der Stadt der {link:forsaken}Verlassenen{/link} darunter. Teile der alten Straßen gehören ihnen noch immer nicht. Truppen der {link:scourge}Geißel{/link} halten sich in den östlichen Ruinen, und die Verlassenen kämpfen darum, sie zurückzuerobern.]=],
		},
	},
})

Translate("deDE", "whispering-forest", {
	title = "Whispering Forest",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Der Whispering Forest liegt in den Bergen des westlichen {link:tirisfal-glades}Tirisfal{/link}, unterhalb der Klippe namens {link:bandarion-keep}Northface Rock{/link}. Seine Wälder sind dunkel, und seine Wurzeln sollen tief reichen. Manche in {link:undercity}Undercity{/link} sagen, der Wald sei von der Leere berührt und unter ihm kröchen Dinge, die es nicht geben dürfte. Kranke Hirsche und Hirschkühe streifen durch seine Lichtungen. An einem Ring großer Pilze wandelt ein geisterhafter Ritter, der durch einen Eid dort gebunden ist. Im Südwesten liegen die Ruinen von {link:shadowvale}Shadowvale{/link}, und über allem thront Bandarion Keep.]=],
		},
	},
})

Translate("deDE", "bandarion-keep", {
	title = "Bandarion Keep",
	aliases = { "Northface Rock" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Bandarion Keep ist das Kloster von {link:tyr-s-watch}Tyr's Watch{/link}, dem Orden der verlassenen Paladine. Es steht auf Northface Rock, der steilen Klippe zwischen dem {link:whispering-forest}Whispering Forest{/link} und dem übrigen {link:tirisfal-glades}Tirisfal{/link}. Im letzten Krieg hielt die {link:argent-dawn}Argentumdämmerung{/link} es gegen die {link:scourge}Geißel{/link}. Als die Dämmerung sich in die Pestländer zurückzog, verfiel die Festung, und die {link:murlocs}Murlocs{/link} der Vile Fin machten sie zu ihrem Laichgrund. {link:danitha-morr}Danitha Morr{/link} und ihre Paladine vertrieben sie und begannen mit dem Wiederaufbau. Sie benannte die Festung nach {link:garek-bandarion}Garek Bandarion{/link}, dem ersten der Verlassenen, der das {link:holy-light}Heilige Licht{/link} wieder aufnahm.]=],
		},
	},
})

Translate("deDE", "shadowvale", {
	title = "Shadowvale",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Shadowvale ist ein zerstörtes Dorf tief im {link:whispering-forest}Whispering Forest{/link}, südwestlich von {link:bandarion-keep}Bandarion Keep{/link}. Seine Bewohner waren zu Lebzeiten seltsam und verschlossen, und Besucher waren ihnen nicht willkommen. Nun gehört das Dorf den Befleckten, auferstandenen Paladinen, die das Licht gegen ihr eigenes Volk wenden. Hirnlose Tote sammeln sich in den Kellern darunter. Ein Kultist soll einen Splitter des Kristalls der Nekropole dort hinuntergetragen haben, und was immer er bewirkt, er macht die Toten stärker oder zahlreicher.]=],
		},
	},
})

Translate("deDE", "tyr-s-watch", {
	title = "Tyr's Watch",
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Tyr's Watch ist ein Orden {link:forsaken}verlassener{/link} Paladine, neu gegründet in {link:tirisfal-glades}Tirisfal{/link}. Seine Mitglieder waren zu Lebzeiten Diener des {link:holy-light}Heiligen Lichts{/link}. Sie starben, erhoben sich und stellten fest, dass das Licht ihnen noch immer antwortete, auch wenn seine Berührung nun ihr Fleisch verbrennt. Sie unterhalten ihr Kloster in {link:bandarion-keep}Bandarion Keep{/link}, und {link:danitha-morr}Danitha Morr{/link} führt sie an.]=],
		},
		{
			title = "Glaube",
			text = [=[Die Paladine von Tyr's Watch lehren, dass Schmerz kein Grund ist, sich vom Licht abzuwenden. Heilung verletzt sie, also lernen sie, durch den Schmerz hindurch zu heilen, und sie nennen es einen Schmelztiegel. Sie lehren, dass das Streben nach dem Guten um seiner selbst willen das Herz ihrer Berufung ist. Sie suchen die Elenden und Vergessenen von {link:undercity}Undercity{/link} auf und helfen ihnen auf kleine Weise, denn sie glauben, dass auch kleine Taten sie an das Licht binden.]=],
		},
		{
			title = "Der Orden und sein Volk",
			text = [=[Die Verlassenen erinnern sich gut daran, was die Lebenden ihnen im Namen des Lichts angetan haben. Viele fürchten, dass ein Paladin sie eines Tages als Ungeheuer niederstrecken wird. Manche auferstandenen Paladine tun genau das. Der Orden nennt sie die Befleckten und jagt sie. Die Dunkle Fürstin selbst misstraut Tyr's Watch und hat seinen Paladinen gesagt, dass sie sie beobachtet. {link:danitha-morr}Danitha{/link} glaubt, dass es Jahre oder Jahrzehnte dauern könnte, bis ihrem Orden voll vertraut wird. Sie will sich dieses Vertrauen dennoch verdienen.]=],
		},
	},
})

Translate("deDE", "shadow-priest-sarvis", {
	title = "Schattenpriester Sarvis",
	subtitle = "Priester von Deathknell",
	found = "Die Kapelle von Deathknell",
	hint = [=[Sprecht mit dem Schattenpriester in der Kapelle von Deathknell.]=],
	allegiance = "Verlassene",
	aliases = { "Sarvis" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Schattenpriester Sarvis hütet die Kapelle am Fuß des Hügels in {link:deathknell}Deathknell{/link}. Wenn die Neuerstandenen kalt und verwirrt aus der Gruft stolpern, ist es Sarvis, der ihnen die Wahrheit sagt. Sie sind tot. Sie sind frei vom Lichkönig. Und sie gehören nun der Dunklen Fürstin, die die Verlassenen in ihrem Krieg gegen die {link:scourge}Geißel{/link} und gegen die {link:humans}Menschen{/link} führt, die sie jagen.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Sarvis gibt den neuen Verlassenen ihre erste Aufgabe. Er schickt sie gegen die hirnlosen Toten des Dorfes, die einstigen Brüder und Schwestern, die nicht in die Gemeinschaft geholt werden konnten.]=],
		},
		{
			title = "Taten",
			text = [=[• Er empfängt die Auferstandenen, die in der Gruft von {link:deathknell}Deathknell{/link} erwachen.
• Er schickt sie aus, die hirnlosen Zombies und die Skelette der Rattlecage zu vernichten.]=],
		},
	},
	mentions = {
		{ text = "Ein böses Erwachen" },
		{ text = "Die Hirnlosen" },
		{ text = "Die Rattlecage aufrütteln" },
	},
	bonds = {
		{ id = "undertaker-mordo", name = "Totengräber Mordo", note = "schickt ihm die Auferstandenen" },
		{ id = "executor-arren", name = "Exekutor Arren", note = "befehligt Deathknell" },
	},
})

Translate("deDE", "undertaker-mordo", {
	title = "Totengräber Mordo",
	subtitle = "Hüter der Gruft",
	found = "Vor der Gruft von Deathknell",
	hint = [=[Sprecht mit dem Totengräber, der vor der Gruft von Deathknell wartet.]=],
	allegiance = "Verlassene",
	aliases = { "Mordo" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Mordo ist der Totengräber von {link:deathknell}Deathknell{/link} und der Hüter seiner Gruft. Oft ist er das erste Gesicht, das ein neuer Verlassener sieht. Er tut nicht so, als sei das Erwachen sanft. Die Leichen, die sich nicht regen, werden verbrannt, und er sagt offen, dass viele, die sich erheben, beinahe mit ihnen ins Feuer gegangen wären.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Mordo steht an der Schwelle zum zweiten Leben der Verlassenen. Jeder, der in {link:deathknell}Deathknell{/link} erwacht, geht durch seine Hände, und er schickt jeden von ihnen zur Kapelle hinunter.]=],
		},
		{
			title = "Taten",
			text = [=[• Er hütet die Gruft von {link:deathknell}Deathknell{/link} und versorgt die Toten, die dorthin gebracht werden.
• Er schickt die Neuerstandenen zu {link:shadow-priest-sarvis}Schattenpriester Sarvis{/link}.]=],
		},
	},
	mentions = {
		{ text = "Ein böses Erwachen" },
	},
	bonds = {
		{ id = "shadow-priest-sarvis", name = "Schattenpriester Sarvis", note = "empfängt die Auferstandenen" },
	},
})

Translate("deDE", "executor-arren", {
	title = "Exekutor Arren",
	subtitle = "Exekutor von Deathknell",
	found = "Deathknell",
	hint = "Sprecht mit dem Exekutor, der Deathknell befehligt.",
	allegiance = "Verlassene · Todeswache",
	aliases = { "Arren" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Exekutor Arren befehligt {link:deathknell}Deathknell{/link}. Er hat wenige Soldaten und viele Sorgen. Spinnen haben die Goldmine überrannt, die sein Volk braucht, und im Südosten ist ein Lager des {link:scarlet-crusade}Scharlachroten Kreuzzugs{/link} entstanden. Er untersteht {link:executor-zygand}Exekutor Zygand{/link} in {link:brill}Brill{/link}, und er schickt jeden fähigen Rekruten aus, um sich um das zu kümmern, was seine Todeswache nicht bewältigen kann.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Arren ist ein nüchterner Befehlshaber. Er verspottet die Eiferer, die keiner Vernunft zugänglich sind, und er kennt den Wert eines abgefangenen Briefes.]=],
		},
		{
			title = "Taten",
			text = [=[• Er befiehlt, die Spinnen aus der Mine im Nachtwebergrund zu vertreiben.
• Er schlägt gegen das Lager des Kreuzzugs nahe {link:deathknell}Deathknell{/link} zu.
• Er schickt die erbeuteten Papiere des Boten nach {link:brill}Brill{/link}.]=],
		},
	},
	chapters = {
		{
			title = "Der rote Bote",
			hint = [=[Haltet den scharlachroten Boten auf, der nach Deathknell gesandt wurde.]=],
			text = [=[Aus {link:brill}Brill{/link} kam Nachricht, das Scharlachrote Kloster habe einen Boten zu den Kreuzfahrern nahe {link:deathknell}Deathknell{/link} geschickt. Arren ließ ihn jagen. Die meisten Papiere, die er bei sich trug, waren wertlos. Eines war es nicht: eine Karte der Befehlshaber und Agenten des Kreuzzugs in den Lichtungen.]=],
		},
	},
	mentions = {
		{ text = "Nachtwebergrund" },
		{ text = "Der Scharlachrote Kreuzzug" },
		{ text = "Der rote Bote" },
		{ text = "Lebenswichtige Informationen" },
	},
	bonds = {
		{ id = "executor-zygand", name = "Exekutor Zygand", note = "sein Vorgesetzter" },
		{ id = "aramis-hammerhand", name = "Aramis Hammerhand", note = "ein Paladin, dem er misstraut" },
	},
})

