Translate("deDE", "gunther-arcanus", {
	title = "Gunther Arcanus",
	subtitle = "Der Lich vom Blendwassersee",
	found = "Gunthers Zufluchtsort, auf der Insel im Blendwassersee",
	hint = "Sucht den Lich, der auf der Insel im Blendwassersee haust.",
	allegiance = "Verlassene",
	aliases = { "Gunther" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Gunther Arcanus war ein Magier der {link:kirin-tor}Kirin Tor{/link} von {link:dalaran}Dalaran{/link} und ein geschickter Nekromant. Er studierte an der Seite von {link:bethor-iceshard}Bethor Iceshard{/link} und {link:thule-ravenclaw}Thule Ravenclaw{/link}. Thule verriet seine Freunde an den Lichkönig. Gunther und Bethor starben an der Seuche. Gunther erhob sich als Lich mit freiem Verstand, doch er glaubte, der Einzige seiner Art zu sein, und er hielt jeden anderen Untoten für einen Sklaven der {link:scourge}Geißel{/link}.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Gunthers Rückkehr ist ein Gewinn für die Verlassenen. Seine Macht ist im Tod gewachsen, und sein Wissen über die Nekromantie ist der Dunklen Fürstin von großem Nutzen.]=],
		},
		{
			title = "Taten",
			text = [=[• Er verlangt Beweise, dass die Verlassenen wahrhaftig Feinde der {link:scourge}Geißel{/link} sind.]=],
		},
	},
	chapters = {
		{
			title = "Der verlorene Lich",
			hint = [=[Bringt den Lich vom Blendwassersee zu seinem alten Freund zurück.]=],
			text = [=[{link:bethor-iceshard}Bethor{/link} legte einen Zauber auf Gunthers gestohlenes Buch, damit Gunther beim Anblick wisse, dass sein alter Freund frei war. Gunther wollte mehr als einen Zauber. Er verlangte den Tod der Agentin der {link:scourge}Geißel{/link} {link:lillith-nefara}Lillith Nefara{/link}. Als sie erschlagen war, glaubte er endlich, dass er nicht allein war.]=],
		},
	},
	mentions = {
