})

Translate("deDE", "garek-bandarion", {
	title = "Garek Bandarion",
	subtitle = "Der erste verlassene Paladin",
	found = "In Bandarion Keep in Erinnerung gehalten",
	hint = [=[Sucht die Festung in den westlichen Hügeln, die seinen Namen trägt.]=],
	allegiance = "Verlassene · Todeswache · einst die Stadtwache von Lordaeron",
	aliases = { "Garek", "Hauptmann Bandarion" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Garek Bandarion war ein Soldat von {link:lordaeron}Lordaeron{/link}, der beim Fall des Königreichs starb und sich unter den {link:forsaken}Verlassenen{/link} erhob. Er wurde der erste Hauptmann der Todeswache, und er war der erste der Verlassenen, der als Paladin das {link:holy-light}Heilige Licht{/link} wieder aufnahm. Er fiel, als die Nekropole {red:naxxramas}Naxxramas{/red} gegen {link:undercity}Undercity{/link} zog. Die Paladine von {link:tyr-s-watch}Tyr's Watch{/link} benannten ihr Kloster nach ihm, und sie rufen seinen Namen noch immer als Schlachtruf.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Für die verlassenen Paladine ist Garek der Beweis, dass das Licht sie im Tod nicht verlassen hat. Für die Todeswache ist er der Hauptmann, der ihre Reihen aufbaute. Sein Leben verbindet die letzten Tage des lebenden Königreichs mit den ersten Tagen des toten.]=],
		},
		{
			title = "Taten",
			text = [=[• Zu Lebzeiten diente er in der Stadtwache der {link:capital-city}Hauptstadt{/link} unter Hauptmann Landen, der ihn zu seinem Nachfolger bestimmte.
• An dem Tag, als {link:arthas-menethil}Arthas{/link} seinen Vater ermordete, führten er und Landen Überlebende durch die Kanäle unter der Stadt hinaus.
• Er nahm Rache an Baron Rivendare, dem Lord, der das Königreich an den {link:cult-of-the-damned}Kult der Verdammten{/link} verriet, und starb an seinen Wunden und an der Seuche.
• Als Verlassener kämpfte er in den ersten Tagen von {link:undercity}Undercity{/link} an der Seite der Dunklen Waldläuferin {link:dark-ranger-anya}Anya{/link}.
• Er stieg zum Hauptmann der Todeswache auf.
• Er starb bei der Verteidigung von Undercity gegen Naxxramas.]=],
		},
	},
	chapters = {
		{
			title = "Die letzten Tage Lordaerons",
			hint = [=[Erfahrt, was die Verlassenen von Undercity über ihren ersten Hauptmann erzählen.]=],
			text = [=[Garek war ein junger Wachsoldat, der sich nach der Schlacht sehnte, und sein Hauptmann Landen sagte ihm, das Volk zu beschützen sei der größere Ruhm. In der Nacht, in der {link:arthas-menethil}Arthas{/link} König {link:terenas-menethil}Terenas Menethil{/link} erschlug, fanden sie den Thronsaal voller Kultisten. {link:uther-the-lightbringer}Uther der Lichtbringer{/link} schickte sie aus, um zu retten, wen sie konnten. Unter der Stadt stellten sie fest, dass der Kult längst bereit war. Landen blieb zurück, um Baron Rivendare aufzuhalten, damit Garek das Volk in Sicherheit führen konnte. Garek vergab dem Baron nie. Er jagte ihn bis Stratholme und tötete ihn dort, und er starb an seinen Wunden.]=],
		},
		{
			title = "Ein zweites Leben",
			hint = [=[Hört, wie die Paladine von Bandarion Keep von ihrem Gründer sprechen.]=],
			text = [=[Garek erwachte in den Gewölben von {link:undercity}Undercity{/link} ohne jede Erinnerung außer seinem Namen. Der Apotheker Putress wollte seinen Körper als Ersatzteile verwenden. Die {link:dark-ranger-anya}Dunkle Waldläuferin Anya{/link} hielt ihn davon ab. Garek schwor {link:sylvanas-windrunner}Sylvanas{/link} die Treue, und mit Anya sammelte er die Toten mit freiem Willen aus den Ruinen, räumte die Tunnel und half der Stadt zu wachsen. Als der {link:scarlet-crusade}Scharlachrote Kreuzzug{/link} die Mauern von Undercity durchbrach, führte er die Todeswache gegen ihn. Irgendwann in jenen Jahren begann das Licht ihm wieder zu antworten.]=],
		},
		{
			title = "Die Festung seines Namens",
			hint = [=[Erfahrt, warum die Festung auf Northface Rock seinen Namen trägt.]=],
			text = [=[Als Naxxramas zu den Ruinen der {link:capital-city}Hauptstadt{/link} kam, bekämpften die Verlassenen und die {link:argent-dawn}Argentumdämmerung{/link} sie gemeinsam an der Oberfläche. Garek kehrte nicht zurück. {link:danitha-morr}Danitha Morr{/link} und {link:leonid-barthalomew}Leonid Barthalomew{/link} kämpften in dieser Schlacht und verloren dort viele Freunde. Als Danitha die alte Festung auf {link:bandarion-keep}Northface Rock{/link} für ihren Orden in Besitz nahm, benannte sie sie nach ihm.]=],
		},
	},
	mentions = {
		{ text = "Eine gerechte Sache" },
		{ text = "{link:bandarion-keep}Bandarion Keep{/link}" },
		{ text = "Die Gerechtigkeit des Lichts" },
	},
	bonds = {
		{ id = "dark-ranger-anya", name = "Dunkle Waldläuferin Anya", note = "seine Gefährtin" },
		{ id = "danitha-morr", name = "Danitha Morr", note = "benannte die Festung nach ihm" },
		{ id = "leonid-barthalomew", name = "Leonid Barthalomew", note = "ein Freund" },
		{ id = "sylvanas-windrunner", name = "Sylvanas Windrunner", note = "seine Königin" },
	},
})

Translate("deDE", "dark-ranger-anya", {
	title = "Dunkle Waldläuferin Anya",
	subtitle = "Dunkle Waldläuferin der Bansheekönigin",
	found = "In diesen Tagen unbekannt",
	hint = "Erfahrt von ihr durch die Erzählungen über Garek Bandarion.",
	allegiance = "Verlassene · einst die Weitschreiter von Quel'Thalas",
	aliases = { "Anya" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Anya ist eine Dunkle Waldläuferin, eine der untoten Elfen, die {link:sylvanas-windrunner}Sylvanas Windrunner{/link} dienen. Zu Lebzeiten war sie eine Waldläuferin von {link:quel-thalas}Quel'Thalas{/link} unter Sylvanas' Befehl. Sie starb bei der Verteidigung ihrer Heimat gegen die {link:scourge}Geißel{/link} und erhob sich als deren Sklavin. Sie erinnert sich an alles, was sie in dieser Zeit tat. Als sie sich befreite, gab Sylvanas ihr einen Ort, an den sie gehörte, und dafür schenkte Anya der Dunklen Fürstin ihre Treue für alle Zeit.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Anya ist eine der ersten Dunklen Waldläuferinnen der {link:forsaken}Verlassenen{/link} und eine von denen, die {link:undercity}Undercity{/link} aus den Tunneln emporwachsen sahen. Sie war die Gefährtin {link:garek-bandarion}Garek{/link} Bandarions in den frühen Kriegen des toten Königreichs. Wo er seine Erinnerungen verlor, behielt sie alle ihre, und sie lehrte ihn, dass der Tod für viele Verlassene ein Neuanfang und ein zweites Leben ist. Den Lebenden traut sie sehr wenig. Als ein Paladin der alten Silbernen Hand einem verlassenen Arbeiter Gnade erwies und sein Hauptmann den Mann dennoch tötete, sagte Anya zu Garek, die Lebenden würden die Untoten niemals als Personen sehen, und man könne ihnen nicht trauen.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie fiel bei der Verteidigung von {link:quel-thalas}Quel'Thalas{/link} und tat als Sklavin des Lichkönigs schreckliche Dinge.
• Sie hielt den Apotheker Putress davon ab, {link:garek-bandarion}Garek{/link} bei seinem Erwachen in Ersatzteile zu zerlegen.
• Sie sagte Garek, sein verlorenes Gedächtnis sei eine Gnade, denn sie erinnere sich nur zu gut an ihre eigenen Verbrechen.
• Mit Garek rettete sie die Toten mit freiem Willen aus den Ruinen der {link:capital-city}Hauptstadt{/link}.
• Sie kämpfte an seiner Seite gegen den Scharlachroten Kreuzzug und gegen Naxxramas.
• Mit {link:sylvanas-windrunner}Sylvanas{/link} und der Dunklen Waldläuferin Clea ritt sie zu {link:the-marris-stead}Marris' Siedlung{/link} auf der Suche nach {link:nathanos-blightcaller}Nathanos Marris{/link}.]=],
		},
		{
			title = "Nicht überliefert",
			text = [=[Keine Chronik dieser Tage verzeichnet, wo Anya jetzt dient oder was sie tat, nachdem {link:garek-bandarion}Garek{/link} gefallen war.]=],
		},
	},
	bonds = {
		{ id = "garek-bandarion", name = "Garek Bandarion", note = "ihr Gefährte" },
		{ id = "sylvanas-windrunner", name = "Sylvanas Windrunner", note = "ihre Königin" },
	},
})

Translate("deDE", "danitha-morr", {
	title = "Danitha Morr",
	subtitle = "Befehlshaberin von Bandarion Keep",
	found = "Bandarion Keep",
	hint = "Sprecht mit der Anführerin der Paladine in Bandarion Keep.",
	allegiance = "Tyr's Watch · Verlassene",
	aliases = { "Danitha" },
	sections = {
		{
			title = "Zusammenfassung",
			text = [=[Danitha Morr führt die Paladine von {link:tyr-s-watch}Tyr's Watch{/link} von {link:bandarion-keep}Bandarion Keep{/link} aus. Sie nennt sich das, was einer Befehlshaberin der Festung am nächsten kommt. Sie kämpfte bei der Verteidigung von {link:undercity}Undercity{/link}, als Naxxramas kam, und sie verlor dort Freunde, darunter {link:garek-bandarion}Garek Bandarion{/link}. Als sie die verfallene Festung auf Northface Rock in Besitz nahm, benannte sie sie nach ihm.]=],
		},
		{
			title = "Bedeutung",
			text = [=[Danitha versucht, was noch kein Verlassener vor ihr getan hat: unter den Toten einen Orden des {link:holy-light}Heiligen Lichts{/link} aufzubauen und ihm einen Platz in ihrem Königreich zu erringen. Ihr Volk fürchtet Paladine. Ihre Königin misstraut ihnen. Sie glaubt, dass das Werk Jahrzehnte dauern könnte, und sie tut es dennoch.]=],
		},
		{
			title = "Taten",
			text = [=[• Sie baut {link:bandarion-keep}Bandarion Keep{/link} mit Bergungsgut aus den Ruinen von {link:shadowvale}Shadowvale{/link} wieder auf.
• Sie jagt die Befleckten, die auferstandenen Paladine, die ihre Klingen gegen die Verlassenen richten.
• Sie schickt ihre Paladine aus, um den Armen von {link:undercity}Undercity{/link} zu helfen.
• Sie schickt ihren Orden in den {link:silverpine-forest}Silberwald{/link}, um das Vertrauen der {link:horde}Horde{/link} zu gewinnen.]=],
		},
		{ title = "Nicht überliefert", text = "Über Danithas Leben vor dem Tod ist wenig geschrieben." },
	},
	chapters = {
		{
			title = "Eine Heimat in den Hügeln",
			hint = [=[Findet Euren Weg nach Bandarion Keep und trefft seine Befehlshaberin.]=],
			text = [=[Die Festung war eine Ruine, als Danithas Paladine kamen. {link:murlocs}Murlocs{/link} der Vile Fin hatten sie zu ihrem Laichgrund gemacht, und sie kämpften darum, sie zurückzuerobern, selbst nachdem sie vertrieben worden waren. Danitha hatte wenig Material, noch weniger Verbündete und sehr viele Mauern auszubessern. Sie hieß jeden Neuankömmling willkommen, der noch am Licht festhielt.]=],
		},
		{
			title = "Die Befleckten",
			hint = [=[Kümmert Euch um die auferstandenen Paladine, die Shadowvale zu ihrem Unterschlupf gemacht haben.]=],
			text = [=[Nicht jeder Paladin, der sich erhebt, kann annehmen, was aus ihm geworden ist. Manche bewahren den Hass ihres alten Lebens und töten die Verlassenen, denen sie begegnen. Jede solche Tötung macht es den Feinden des Ordens leichter, Furcht zu schüren. Danitha ließ die Befleckten von {link:shadowvale}Shadowvale{/link} vernichten und ihren Befehlshaber {link:rudolph-gelhardt}Rudolph Gelhardt{/link} enthaupten.]=],
		},
		{
			title = "Ein Zeichen guten Willens",
			hint = "Überbringt Danithas Geschenk der Dunklen Fürstin.",
			text = [=[Danitha schickte Gelhardts Kopf nach {link:undercity}Undercity{/link}, um der Dunklen Fürstin zu zeigen, dass {link:tyr-s-watch}Tyr's Watch{/link} im eigenen Haus Ordnung hält. {link:sylvanas-windrunner}Sylvanas{/link} zweifelte nicht an Danithas Aufrichtigkeit. Sie sagte, sie erwarte, dass weitere Paladine dem Wahnsinn verfallen würden, und dass sie eines Tages beschließen könnte, den Orden nicht länger zu dulden. Sie sagte seinen Paladinen, sie sollten gut dienen, und sie werde sie beobachten.]=],
		},
	},
	mentions = {
		{ text = "Ein Rundgang über das Gelände" },
		{ text = "Die Befleckten" },
		{ text = "Ein Zeichen guten Willens" },
		{ text = "Eine Lektion in Göttlichkeit" },
		{ text = "Ein diplomatischer Zwischenfall" },
		{ text = "Eine gerechte Sache" },
	},
	bonds = {
		{ id = "garek-bandarion", name = "Garek Bandarion", note = "ein gefallener Freund" },
		{ id = "leonid-barthalomew", name = "Leonid Barthalomew", note = "ein alter Kampfgefährte" },
		{ id = "rudolph-gelhardt", name = "Rudolph Gelhardt", note = "der Befehlshaber der Befleckten" },
		{ id = "sylvanas-windrunner", name = "Sylvanas Windrunner", note = "misstraut ihrem Orden" },
	},
})

Translate("deDE", "leonid-barthalomew", {
	title = "Leonid Barthalomew",
	subtitle = "Gesandter der Argentumdämmerung",
	found = "Bandarion Keep",
	hint = [=[Sprecht mit dem untoten Gesandten der Argentumdämmerung in Bandarion Keep.]=],
	allegiance = "Argentumdämmerung",
	aliases = { "Leonid", "Leonid Barthalomew der Verehrte" },
	sections = {
		{
			title = "Zusammenfassung",
